package app.studyforge.mobile;
import org.json.*;
import java.util.*;

final class FeatureController {
    private final StudyApp app;JSONObject practice;
    FeatureController(StudyApp app){this.app=app;}
    void example(String owner) throws Exception {JSONObject p=FeatureProgram.validate(new JSONObject(Api.read(app.getAssets().open("feature-example.json"),200000)));synchronized(app){if(!owner.equals(app.profile)||app.busy)throw new Exception("계정이나 작업 상태가 바뀌었습니다.");Object before=app.workspace.opt("featureDraft");app.workspace.put("featureDraft",Json.object("id",UUID.randomUUID().toString(),"baseRevision",0,"program",p,"hash",FeatureProgram.hash(p),"request","로컬 복습 큐 예제 · AI 요청 없음"));try{app.save();}catch(Exception e){if(before==null)app.workspace.remove("featureDraft");else app.workspace.put("featureDraft",before);throw e;}app.state();app.notice("로컬 예제 변경안입니다. AI 요청은 보내지 않았습니다. 미리보기에서 실제 동작을 검사할 수 있습니다.");}}
    void propose(JSONObject request) throws Exception {
        final String owner,instruction=request.optString("instruction").trim(),id,model;final JSONObject snapshot,previous;final int base;final long token;
        if(instruction.length()<3||instruction.length()>4000)throw new Exception("기능 요청을 3~4,000자로 입력하세요.");
        synchronized(app){if(app.busy)throw new Exception("현재 작업을 마친 뒤 기능을 만들어 주세요.");owner=app.profile;model=app.selectedModel(request);app.workspace.put("model",model);app.save();snapshot=Json.copy(app.workspace);String selected=request.optString("featureId");JSONObject existing=FeatureVersions.find(snapshot.optJSONArray("features"),selected),draft=snapshot.optJSONObject("featureDraft");if(existing==null&&!selected.isEmpty()&&(draft==null||!selected.equals(draft.optString("id"))))throw new Exception("수정할 기능을 찾지 못했습니다.");id=selected.isEmpty()?UUID.randomUUID().toString():selected;base=existing==null?0:existing.optInt("revision");previous=draft!=null&&id.equals(draft.optString("id"))?draft:existing;JobService.begin(app,"요청한 기능을 만들고 있습니다.");app.busy=true;token=++app.job;app.state();}
        app.worker.execute(()->{try{JSONObject program=FeatureBuilder.build(instruction,previous,snapshot,(rules,text)->{app.checkJob(token,owner);return QuestionValidator.parse(Api.responses(StudyGenerator.request(model,rules,Json.array(Json.object("type","input_text","text",text))),app.connection.accessToken(),app::progress));},app::progress);synchronized(app){app.checkJob(token,owner);Object before=app.workspace.opt("featureDraft");app.workspace.put("featureDraft",Json.object("id",id,"baseRevision",base,"program",program,"hash",FeatureProgram.hash(program),"request",instruction,"createdAt",System.currentTimeMillis()));try{app.save();}catch(Exception e){if(before==null)app.workspace.remove("featureDraft");else app.workspace.put("featureDraft",before);throw e;}}app.notice("기능 변경안을 만들었어요. 실제 동작 미리보기에서 검사한 뒤 적용하세요.");}catch(Exception e){if(token==app.job)app.notice(e.getMessage());}finally{if(token==app.job){app.busy=false;app.state();JobService.end(app);}}});
    }
    synchronized JSONObject launch(String id,boolean preview) throws Exception {synchronized(app){JSONObject f=preview?app.workspace.optJSONObject("featureDraft"):FeatureVersions.find(app.workspace.optJSONArray("features"),id);if(f==null||!id.equals(f.optString("id"))||!preview&&!f.optBoolean("enabled"))throw new Exception("실행할 기능을 찾지 못했습니다.");JSONObject p=FeatureProgram.validate(f.getJSONObject("program"));String dataset=dataset();JSONObject data=app.workspace.optJSONObject("featureData"),saved=data==null?null:data.optJSONObject(id+":"+dataset);JSONObject exposed=Json.copy(f);exposed.remove("revisions");exposed.remove("undoConfig");exposed.remove("appliedConfig");return Json.object("feature",exposed,"context",FeatureBuilder.context(app.workspace,p,saved),"owner",app.profile,"dataset",dataset,"preview",preview);}}
    String dataset(){return app.workspace.optJSONObject("dataset")==null?"workspace":app.workspace.optJSONObject("dataset").optString("id","workspace");}
    void guard(String owner,String dataset) throws Exception {if(!app.profile.equals(owner)||!dataset().equals(dataset))throw new Exception("계정이나 학습실이 바뀌어 기능을 닫았습니다.");}
    void checks(JSONObject launch,JSONObject report) throws Exception {synchronized(app){guard(launch.getString("owner"),launch.getString("dataset"));if(!launch.getBoolean("preview"))return;JSONObject draft=app.workspace.optJSONObject("featureDraft");if(draft==null||!launch.getJSONObject("feature").getString("hash").equals(draft.optString("hash")))return;JSONArray rows=report.getJSONArray("rows");boolean passed=rows.length()==draft.getJSONObject("program").getJSONArray("tests").length();JSONArray clean=new JSONArray();for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);passed&=row.optBoolean("passed");clean.put(Json.object("name",row.optString("name").substring(0,Math.min(120,row.optString("name").length())),"passed",row.optBoolean("passed"),"error",row.optString("error").substring(0,Math.min(500,row.optString("error").length()))));}Object old=draft.opt("checks");draft.put("checks",Json.object("passed",passed,"rows",clean,"at",System.currentTimeMillis(),"hash",draft.getString("hash")));try{app.save();}catch(Exception e){if(old==null)draft.remove("checks");else draft.put("checks",old);throw e;}app.state();}}
    void install(String id,String hash,String owner) throws Exception {synchronized(app){if(!owner.equals(app.profile))throw new Exception("계정이 바뀌었습니다.");JSONObject d=app.workspace.optJSONObject("featureDraft");if(d==null||!id.equals(d.optString("id"))||!hash.equals(d.optString("hash"))||!FeatureProgram.hash(d.getJSONObject("program")).equals(hash))throw new Exception("변경안이 바뀌었습니다. 다시 미리보기 해주세요.");JSONObject checks=d.optJSONObject("checks");if(checks==null||!checks.optBoolean("passed")||!hash.equals(checks.optString("hash")))throw new Exception("실제 동작 미리보기의 자동 검사를 먼저 통과해야 합니다.");JSONObject current=FeatureVersions.find(app.workspace.optJSONArray("features"),id);if((current==null?0:current.optInt("revision"))!=d.optInt("baseRevision"))throw new Exception("원래 기능의 버전이 바뀌었습니다. 변경안을 다시 만들어 주세요.");if(current==null&&app.workspace.optJSONArray("features")!=null&&app.workspace.getJSONArray("features").length()>=20)throw new Exception("시제품은 개인 기능 20개까지 보관합니다.");JSONObject before=app.workspace;app.workspace=FeatureVersions.apply(before,d);try{app.save();}catch(Exception e){app.workspace=before;throw e;}app.state();app.notice("새 기능을 적용했어요. 기능 목록에서 열거나 말로 다시 고칠 수 있습니다.");}}
    void undo(String id,String owner) throws Exception {synchronized(app){if(!owner.equals(app.profile))throw new Exception("계정이 바뀌었습니다.");JSONObject before=app.workspace;app.workspace=FeatureVersions.undo(before,id);try{app.save();}catch(Exception e){app.workspace=before;throw e;}app.state();app.notice("기능 적용을 되돌렸어요. 문제·풀이 기록과 기능 보관 데이터는 유지합니다.");}}
    JSONObject saveData(JSONObject launch,JSONObject value) throws Exception {synchronized(app){guard(launch.getString("owner"),launch.getString("dataset"));JSONObject p=launch.getJSONObject("feature").getJSONObject("program");if(!FeatureProgram.permits(p,"state.write"))throw new Exception("이 기능에는 보관 권한이 없습니다.");JSONObject clean=FeatureBuilder.state(value);if(launch.getBoolean("preview"))return clean;String id=launch.getJSONObject("feature").getString("id");JSONObject current=FeatureVersions.find(app.workspace.optJSONArray("features"),id);if(current==null||!current.optBoolean("enabled")||!launch.getJSONObject("feature").getString("hash").equals(current.optString("hash")))throw new Exception("기능이 개정되거나 비활성화됐습니다.");JSONObject all=app.workspace.optJSONObject("featureData");if(all==null){all=new JSONObject();app.workspace.put("featureData",all);}String key=id+":"+launch.getString("dataset");Object old=all.opt(key);all.put(key,clean);try{app.save();}catch(Exception e){if(old==null)all.remove(key);else all.put(key,old);throw e;}return clean;}}
    void practice(JSONObject launch,JSONArray ids) throws Exception {synchronized(app){guard(launch.getString("owner"),launch.getString("dataset"));if(launch.getBoolean("preview")||!FeatureProgram.permits(launch.getJSONObject("feature").getJSONObject("program"),"practice.open"))throw new Exception("미리보기에서는 실제 재풀이를 시작하지 않습니다.");practice=Json.object("owner",app.profile,"dataset",dataset(),"ids",FeatureBuilder.practice(app.workspace,ids),"token",UUID.randomUUID().toString());app.state();}}
    JSONObject practiceState(){synchronized(app){try{if(practice!=null){guard(practice.getString("owner"),practice.getString("dataset"));return practice;}}catch(Exception ignored){practice=null;}return new JSONObject();}}
}
